file.content:
    return {"enabled": enabled}

# ---- DKG 节点健康 ------------------------------------------------------

@staticmethod
def _normalize_node_state_value(value: object) -> dict:
    """校验并归一单个节点健康值：须为恰含 ``key``/``state`` 两键的对象，
    key 为 64 位小写 hex，state ∈ up|down|ban；非法抛 ServiceError(400)。

    返回值固定键序 key,state。"""
    if not isinstance(value, dict) or set(value) != {"key", "state"}:
        raise ServiceError(
            400, "each node value must contain exactly key and state"
        )
    key = value["key"]
    state = value["state"]
    if not _is_lower_hex_32(key):
        raise ServiceError(
            400, "node key must be 64 lowercase hex characters"
        )
    if state not in DKG_NODE_STATES:
        raise ServiceError(
            400,
            "node state must be one of " + ", ".join(DKG_NODE_STATES),
        )
    return {"key": key, "state": state}

def _normalize_nodes_body(self, nodes: object) -> dict:
    """校验 PUT nodes 请求体 Q 的 nodes 表并归一。

    nodes 须为非空对象，键为安全标识且不重复（dict 天然唯一）；每值恰
    含 key(64 位小写 hex)/state(up|down|ban)。归一为按节点 ID 升序的
    表，每值键序 key,state。非法抛 ServiceError(400)。"""
    if not isinstance(nodes, dict) or not nodes:
        raise ServiceError(
            400, "nodes must be a non-empty object keyed by node id"
        )
    # 先确认键全为合法标识，再排序（混合类型键会让 sorted 抛
    # TypeError，必须在排序前拦住，统一落 400 而非 503）。
    for node_id in nodes:
        if not isinstance(node_id, str) or not ROTATION_ID_RE.match(
            node_id
        ):
            raise ServiceError(
                400, "node id must match [A-Za-z0-9_-]{1,128}"
            )
    normalized: dict[str, dict] = {}
    for node_id in sorted(nodes):
        normalized[node_id] = self._normalize_node_state_value(
            nodes[node_id]
        )
    return normalized

def _node_state_events_strict(self, wallet_id: str) -> list[dict]:
    """返回该钱包全部 node_state 事件（按 seq 升序），逐条严格校验。

    每条事件 request_id/actor_id/reason 必须为 null，details 恰含
    ``nodes``：非空、键为安全标识且升序唯一、每值恰含 key(64 位小写
    hex)/state(up|down|ban)。任何畸形/矛盾都是不可对账现场
    （RecoveryError，fail-closed），绝不静默忽略。纯只读，不分配
    seq。"""
    events = self._audit.events_by_type(wallet_id, audit.TYPE_NODE_STATE)
    for event in events:
        if (
            event.get("request_id") is not None
            or event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a node_state event with "
                "request_id/actor/reason set"
            )
        details = event.get("details")
        if not isinstance(details, dict) or set(details) != {"nodes"}:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a malformed node_state event"
            )
        nodes = details["nodes"]
        if not isinstance(nodes, dict) or not nodes:
            raise RecoveryError(
                f"wallet {wallet_id!r} has an empty or malformed "
                "node_state nodes table"
            )
        # 排序前先确认键全为字符串（损坏现场可能含非字符串键，直接
        # sorted 会抛 TypeError 而绕过 fail-closed 包装）。
        if any(not isinstance(k, str) for k in nodes):
            raise RecoveryError(
                f"wallet {wallet_id!r} node_state has a non-string "
                "node id"
            )
        keys = list(nodes)
        if keys != sorted(keys) or len(set(keys)) != len(keys):
            raise RecoveryError(
                f"wallet {wallet_id!r} node_state nodes are not in "
                "strictly ascending order"
            )
        for node_id, entry in nodes.items():
            if not ROTATION_ID_RE.match(node_id):
                raise RecoveryError(
                    f"wallet {wallet_id!r} node_state has a malformed "
                    "node id"
                )
            if (
                not isinstance(entry, dict)
                or set(entry) != {"key", "state"}
                or not _is_lower_hex_32(entry.get("key"))
                or entry.get("state") not in DKG_NODE_STATES
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} node_state has a malformed "
                    f"entry for node {node_id!r}"
                )
    return events

def _latest_node_states_locked(self, wallet_id: str) -> Optional[dict]:
    """从 node_state 事件恢复当前节点健康表（取最后一条，已严格校验）。

    无任何 node_state 事件返回 None（GET 未配置 404）。调用方须已持
    钱包锁且已完成审计对账。"""
    events = self._node_state_events_strict(wallet_id)

def _parse_round_param(round_param: object) -> int:
    """解析 ?round= 查询参数：须为规范十进制正整数，否则 400。"""
    if (
        not isinstance(round_param, str)
        or not round_param.isascii()
        or not round_param.isdigit()
    ):
        raise ServiceError(400, "round must be a positive integer")
    try:
        round_no = int(round_param)
    except ValueError:
        raise ServiceError(400, "round must be a positive integer")
    if round_no < 1 or str(round_no) != round_param:
        raise ServiceError(400, "round must be a positive integer")
    return round_no

def _resolve_dkg_round(
    self, session: dict | None, round_param: object
) -> int:
    """把 ?round= 参数解析为要操作的轮次号。

    无任何故障轮次时 P 无需参照轮次（行为与旧版一致，显式
    ?round=1 亦接受）；存在故障轮次后必须显式给出当前轮：缺参
    409、旧轮 409、未知轮 404、非法参数 400。"""
    requested = (
        self._parse_round_param(round_param)
        if round_param is not None
        else None
    )
    if session is None:
        # 会话尚不存在：仅 register 可经第 1 轮创建
        if requested is None or requested == 1:
            return 1
        raise ServiceError(404, f"round {requested} not found")
    current = session["current"]
    if requested is None:
        if current > 1:
            raise ServiceError(
                409, "round query parameter is required"
            )
        return 1
    if requested > current:
        raise ServiceError(404, f"round {requested} not found")
    if requested < current:
        raise ServiceError(
            409, f"round {requested} is not the current round"
        )
    return requested

def get_dkg_session(
    self, wallet_id: str, dkg_id: str, round_param: object = None
) -> dict:
    """查询 DKG 会话当前轮视图；钱包/会话未知 404，dkg id 非法 400。

    存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
    404、非法 400）；aborted 轮一律 409。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            session = self._dkg_sessions(wallet_id).get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            round_no = self._resolve_dkg_round(session, round_param)
            if session["rounds"][round_no]["state"] == "aborted":
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            return self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_stage(
    self,
    wallet_id: str,
    dkg_id: object,
    op: object,
    node: object,
    key: object,
    hash_value: object,
    peer: object,
    round_param: object = None,
) -> tuple[int, dict]:
    """推进两方 DKG 会话当前轮一个阶段，返回 (状态码, 会话视图)。

    - 钱包未知 404；非 register 的未知会话 404；参数非法 400；
    - 首提 201；同值重放 200（优先于阶段判定）；异值/错阶段/第三
      节点 409；
    - 双方依序推进 register→commit→share→done：register 仅 key
      非 null（64 位小写 hex），commit 仅 hash 非 null（64 位小写
      sha256），share 仅 hash/peer 非 null 且 hash 等于 peer 承诺
      （份额链下交换，后端不收正文）；
    - 存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
      404、非法 400）；aborted 轮一律 409；派生轮不接受 register，
      commit/share 沿用旧约；
    - dkg_stage 事件（request_id 为会话 id 或 ``<id>/<轮次>``，
      details 依次 id,op,node,key,hash,peer,state，未用值 null）
      是唯一持久化与提交点：首提在跨进程事务锁内追加，重放不记；
      事件之外不写任何状态，崩溃后由事件序列重建。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            if op not in DKG_OPS:
                raise ServiceError(
                    400,
                    "op must be one of " + ", ".join(DKG_OPS),
                )
            self._validate_dkg_node(node)
            if op == "register":
                if not _is_lower_hex_32(key):
                    raise ServiceError(
                        400, "key must be 64 lowercase hex characters"
                    )
                if hash_value is not None or peer is not None:
                    raise ServiceError(
                        400, "register accepts only a non-null key"
                    )
            elif op == "commit":
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None or peer is not None:
                    raise ServiceError(
                        400, "commit accepts only a non-null hash"
                    )
            else:  # share
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None:
                    raise ServiceError(
                        400, "share accepts only non-null hash and peer"
                    )
                self._validate_dkg_node(peer)
            sessions = self._dkg_sessions(wallet_id)
            session = sessions.get(dkg_id)
            if session is None:
                if op != "register":
                    # 非 register 的未知流程 404
                    raise ServiceError(
                        404, f"dkg session {dkg_id!r} not found"
                    )
                round_no = self._resolve_dkg_round(None, round_param)
                session = {
                    "id": dkg_id,
                    "rounds": {
                        1: {
                            "round": 1,
                            "nodes": [],
                            "commits": {},
                            "shared": {},
                            "state": "register",
                        }
                    },
                    "current": 1,
                    "failovers": {},
                }
            else:
                round_no = self._resolve_dkg_round(session, round_param)
            round_state = session["rounds"][round_no]
            if round_state["state"] == "aborted":
                # aborted 轮一律 409
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            if round_no >= 2 and op == "register":
                # 派生轮的节点槽位由故障轮次确定，不接受 register
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} does "
                    "not accept register",
                )
            if op == "register":
                registered = dict(round_state["nodes"])
                if node in registered:
                    # 同值重放 200 优先；异值 409
                    if registered[node] != key:
                        raise ServiceError(
                            409,
                            f"node {node!r} already registered a "
                            "different key",
                        )
                    return 200, self._dkg_view(session, round_no)
                if len(round_state["nodes"]) >= 2:
                    # 已有两方后的新注册即第三节点
                    raise ServiceError(
                        409,
                        f"dkg session {dkg_id!r} already has "
                        "two nodes",
                    )
            else:
                node_ids = [n for n, _ in round_state["nodes"]]
                if op == "commit":
                    if node in round_state["commits"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["commits"][node] != hash_value:
                            raise ServiceError(
                                409,
                                f"node {node!r} already committed a "
                                "different hash",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "commit":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "commit stage",
                        )
                else:  # share
                    if node in round_state["shared"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["shared"][node] != (
                            hash_value,
                            peer,
                        ):
                            raise ServiceError(
                                409,
                                f"node {node!r} already shared with "
                                "different parameters",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "share":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "share stage",
                        )
                    if peer == node or peer not in node_ids:
                        raise ServiceError(
                            409, f"peer {peer!r} is not the other node"
                        )
                    if round_state["commits"][peer] != hash_value:
                        raise ServiceError(
                            409,
                            "hash does not match the peer commitment",
                        )
            # 首次提交：应用阶段推进并以 dkg_stage 事件为唯一提交点
            # （在跨进程事务锁内追加；事件之外无任何状态落盘，崩溃后
            # 由事件序列重建，无需回滚）。
            if op == "register":
                round_state["nodes"].append((node, key))
            elif op == "commit":
                round_state["commits"][node] = hash_value
            else:
                round_state["shared"][node] = (hash_value, peer)
            round_state["state"] = self._dkg_state(
                round_state["nodes"],
                round_state["commits"],
                round_state["shared"],
            )
            request_id = (
                dkg_id if round_no == 1 else f"{dkg_id}/{round_no}"
            )
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_DKG_STAGE,
                    request_id=request_id,
                    details={
                        "id": dkg_id,
                        "op": op,
                        "node": node,
                        "key": key,
                        "hash": hash_value,
                        "peer": peer,
                        "state": round_state["state"],
                    },
                ),
            )
            return 201, self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_failover(
    self,
    wallet_id: str,
    dkg_id: object,
    round_no: object,
    action: object,
    node: object,
    replacement: object,
    key: object,
    approval_request_id: object = _NO_APPROVAL,
) -> tuple[int, dict]:
    """为两方 DKG 会话提交一个故障轮次，返回 (状态码, 新轮视图)。

    - 钱包/会话未知 404；参数非法 400；
    - 首轮故障基于基线轮，后续基于当前轮：round 必须恰为当前轮 +1；
    - 首提 201；同参重放 200（优先于状态判定）；异参 409；
    - abort 仅限非终态轮，node/replacement/key 必须全为 null，
      派生轮为 aborted 且三数组为空；
    - replace 手工模式：replacement/key 双非 null，仅限两方已注册的

        return 201, self._dkg_view(session, round_no)
except CorruptDataError:
    raise
except ValueError:
    # wallet_id 含非法字符（构造锁路径时抛出）
    raise ServiceError(400, "invalid wallet_id")

def _audit_event(
    event_type: str,
    request_id=None,
    actor_id=None,
    reason=None,
    details=None,
) -> dict:
    """构造审计事件（seq 由 AuditStore 分配）。"""
    return {
        "type": event_type,
        "at": _utc_now_iso(),
        "request_id": request_id,
        "actor_id": actor_id,
        "reason": reason,
        "details": details,
    }

def _emit(self, wallet_id: str, event: dict) -> None:
    self._audit.append_event(wallet_id, event)

# ---- 建钱包 ---------------------------------------------------------

def create_wallet(self, wallet_id: object, shares: object) -> dict:
    if not isinstance(wallet_id, str) or not wallet_id:
        raise ServiceError(400, "wallet_id must be a non-empty string")
    # bool 是 int 的子类，必须先排除；2.0 == 2，必须要求真正的 int
    if not isinstance(shares, int) or isinstance(shares, bool):
        raise ServiceError(400, "shares must equal 2")
    if shares != REQUIRED_SHARES:
        raise ServiceError(400, "shares must equal 2")

"""测试辅助：在临时目录上构造 service，并启动真实 HTTP 服务器。"""

from __future__ import annotations

import json
import threading
import urllib.error
import urllib.request
from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass

from threshold_wallet import crypto
from threshold_wallet.server import create_server
from threshold_wallet.service import WalletService
from threshold_wallet.store import WalletStore


@dataclass
class Harness:
    tmpdir: str
    store: WalletStore
    service: WalletService

    def share_signature(self, wallet_id: str, share_id: str,
                        signing_request_id: str, message: str) -> str:
        """模拟某一份额持有方：用本地份额私钥对拼接载荷签名，返回 hex。"""
        share = self.store.get_share(wallet_id, share_id)
        payload = crypto.build_payload(signing_request_id, message)
        return crypto.sign_share(
            bytes.fromhex(share["private_key"]), payload
        ).hex()

    def two_signatures(self, wallet_id: str, signing_request_id: str,
                       message: str) -> list[dict]:
        return [
            {
                "share_id": sid,
                "signature": self.share_signature(
                    wallet_id, sid, signing_request_id, message
                ),
            }
            for sid in ("share-1", "share-2")
        ]

    def share_private_hex(self, wallet_id: str, share_id: str) -> str:
        return self.store.get_share(wallet_id, share_id)["private_key"]


def make_harness(tmpdir: str) -> Harness:
    store = WalletStore(tmpdir)
    return Harness(tmpdir=tmpdir, store=store, service=WalletService(store))


@dataclass
class RunningServer:
    harness: Harness
    base_url: str
    logs: list[str]
    _httpd: object

    def stop(self) -> None:
        self._httpd.shutdown()
        self._httpd.server_close()

    def request(self, method: str, path: str, body=None):
        data = None
        headers = {"Accept": "application/json"}
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(
            self.base_url + path, data=data, method=method, headers=headers
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read().decode("utf-8"))


@contextmanager
def http_server(tmpdir: str) -> Iterator[RunningServer]:
    """在后台线程启动真实 HTTP 服务器，端口由内核分配。"""
    harness = make_harness(tmpdir)
    logs: list[str] = []
    httpd = create_server("127.0.0.1", 0, harness.service, trace=logs.append)
    port = httpd.server_address[1]
    thread = threading.Thread(
        target=httpd.serve_forever, kwargs={"poll_interval": 0.02}, daemon=True
    )
    thread.start()
    running = RunningServer(
        harness=harness,
        base_url=f"http://127.0.0.1:{port}",
        logs=logs,
        _httpd=httpd,
    )
    try:
        yield running
    finally:
        running.stop()
        thread.join(timeout=2)

    for event in events:
        if not isinstance(event, dict) or set(event) != _AUDIT_EVENT_KEYS:
            raise BackupError(503, "audit event has an unexpected shape")
        if event.get("type") not in _KNOWN_AUDIT_TYPES:
            raise BackupError(503, "audit file has an unknown event type")


def _validate_manifest_shape(
    manifest: object, files: dict[str, bytes]
) -> dict:
    """校验 manifest v1 形状、成员清单与每项字节/sha256，以及 S 绑定哈希。

    manifest 顶层与每个 files 项都只允许契约键：任何额外键（夹带的标识、
    私钥材料或未知扩展）一律 503，绝不静默忽略后继续。"""
    if not isinstance(manifest, dict):
        raise BackupError(503, "manifest is not a JSON object")
    if not set(manifest) <= _MANIFEST_TOP_KEYS:
        raise BackupError(503, "manifest has an unexpected top-level key")
    if manifest.get("version") != MANIFEST_VERSION:
        raise BackupError(503, "unsupported manifest version")
    wallet_id = manifest.get("wallet_id")
    snapshot_id = manifest.get("snapshot_id")
    if not is_safe_id(wallet_id) or not is_safe_id(snapshot_id):
        raise BackupError(503, "manifest has invalid wallet or snapshot id")
    entries = manifest.get("files")
    if not isinstance(entries, list):
        raise BackupError(503, "manifest files must be a list")
    bound = manifest.get("manifest_sha256")
    if not isinstance(bound, str) or not _is_sha256_hex(bound):
        raise BackupError(503, "manifest is missing its binding hash")
    if sha256_hex(_canonical_manifest_body(manifest)) != bound:
        raise BackupError(503, "manifest binding hash mismatch")
    # 归一为"规范主体 + 绑定哈希"：保证同 S 同哈希的重放返回与首次逐字节
    # 一致的 manifest（同体），忽略包内任何额外键/排版差异。
    normalized = json.loads(_canonical_manifest_body(manifest))
    normalized["manifest_sha256"] = bound
    seen: set[str] = set()
    prev_path: Optional[str] = None
    for entry in entries:
        if not isinstance(entry, dict):
            raise BackupError(503, "manifest entry is not an object")
        if not set(entry) <= _MANIFEST_ENTRY_KEYS:
            raise BackupError(503, "manifest entry has an unexpected key")
        path = entry.get("path")
        nbytes = entry.get("bytes")
        digest = entry.get("sha256")
        if not isinstance(path, str) or path in seen:
            raise BackupError(503, "manifest has a missing or duplicate path")
        # 契约要求 files 项严格按 path 升序：即使绑定哈希自洽（包可被整体
        # 重造），乱序清单也不是合法快照形状，绝不据其恢复或落 committed。
        if prev_path is not None and path <= prev_path:
            raise BackupError(503, "manifest files are not sorted by path")
        prev_path = path
        seen.add(path)
        if not _is_whitelisted(wallet_id, path):
            raise BackupError(503, "manifest lists a non-whitelisted path")
        if not isinstance(nbytes, int) or isinstance(nbytes, bool) or nbytes < 0:
            raise BackupError(503, "manifest entry has a bad byte count")
        if not isinstance(digest, str) or not _is_sha256_hex(digest):
            raise BackupError(503, "manifest entry has a bad sha256")
        data = files.get(path)
        if data is None or len(data) != nbytes or sha256_hex(data) != digest:
            raise BackupError(503, "snapshot file fails its manifest hash")
    extra = set(files) - seen
    if extra:
        raise BackupError(503, "snapshot contains files absent from the manifest")
    if not any(p == f"wallets/{wallet_id}.json" for p in seen):
        raise BackupError(503, "snapshot is missing the wallet metadata file")
    # 激活备份（*.bak.json）只是激活事务窗口内的瞬态文件，持锁备份前的
    # 自愈必然已回滚/清理：合法快照里出现它们等于打包了半状态，拒绝。
    if any(
        p.startswith(f"rotation-staging/{wallet_id}/")
        and p.endswith(".bak.json")
        for p in seen
    ):
        raise BackupError(503, "snapshot must not carry transient rotation backups")
    return normalized


def _load_json_object(data: bytes, what: str) -> dict:
    try:
        value = json.loads(data.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise BackupError(503, f"{what} is not valid JSON") from exc
    if not isinstance(value, dict):
        raise BackupError(503, f"{what} must be a JSON object")
    return value


