def _recover_node_rejoins(self, wallet_id: str) -> None:
    """严格复核全部 node_rejoined 提交点（启动恢复与持锁访问共用）。

    每条 node_rejoined 事件除形状外还须按其**提交时刻**现场复核：
    - 事前健康表：seq 之前最近的 node_state 快照必须存在且含 node，
