            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} node "
                "was not down or banned beforehand"
            )
        if before_entry["key"] != key:
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} key "
                "does not match the prior health snapshot"
            )
