        flip_event = by_seq.get(seq - 1)
        if (
            flip_event is None
            or flip_event.get("type") != audit.TYPE_NODE_STATE
        ):
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} is "
                "not committed atomically with a node_state snapshot"
