            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} round "
                "was not in the commit or share stage at commit time"
            )
        if node in nodes_at:
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} node "
                "still occupied a slot at commit time"
            )
        # ---- 审批复核 ------------------------------------------------
        actor_id = event["actor_id"]
        record = self._store.get_request(wallet_id, actor_id)
        if record is None:
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} "
                "approval request is missing"
            )
        if record.get("message") != self._rejoin_approval_message(
            rejoin_id, dkg_id, round_no, node, key
        ):
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} "
                "approval message mismatch"
            )
        if record.get("state") != "approved":
            fail(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} "
                "approval request is not approved"
            )

@staticmethod
def _dkg_event_session_id(event: dict) -> Optional[str]:
    """从 dkg_stage/dkg_failover 事件的 request_id 取会话 id。"""
    request_id = event.get("request_id")
    if not isinstance(request_id, str):
        return None
    return request_id.split("/", 1)[0]

def _dkg_round_state_at_seq(
    self,
    dkg_events: list[dict],
    dkg_id: str,
    round_no: int,
    seq: int,
) -> tuple[list[str], str]:
    """重算某 DKG 会话某轮在 seq 之前的（节点表, 阶段）。

    节点表取该轮 register（基线）/failover（派生）在 seq 前确定的槽位；
    阶段由 seq 前该轮 dkg_stage 事件计数推导（register→commit→share→
    done）。"""
    nodes: list[str] = []
    commits = 0
    shares = 0
    for event in dkg_events:
        if event["seq"] >= seq:
            continue
        if self._dkg_event_session_id(event) != dkg_id:
            continue
        details = event.get("details")
        if not isinstance(details, dict):
            continue
        if event.get("type") == audit.TYPE_DKG_FAILOVER:
            if details.get("round") == round_no:
                nodes = list(details.get("replacement_slots", ()))
            continue
        # dkg_stage：仅统计该轮事件
        request_id = event.get("request_id")
        event_round = (
            1
            if request_id == dkg_id
            else (
                int(request_id.rsplit("/", 1)[1])
                if isinstance(request_id, str)
                and "/" in request_id
                and request_id.rsplit("/", 1)[0] == dkg_id
                else None
            )
        )
        if event_round != round_no:
            continue
        op = details.get("op")
        stage_node = details.get("node")
        if op == "register":
            if stage_node not in nodes:
                nodes.append(stage_node)
        elif op == "commit":
            commits += 1
        elif op == "share":
            shares += 1
    if shares >= 2:
        stage = "done"
    elif commits >= 2:
        stage = "share"
    elif len(nodes) >= 2:
        stage = "commit"
    else:
        stage = "register"
    return nodes, stage

