        ev
        for ev in all_events
        if ev["seq"] < cutoff
        and self._dkg_event_session_id(ev) == dkg_id
        and ev.get("type")
        in (audit.TYPE_DKG_STAGE, audit.TYPE_DKG_FAILOVER)
